-- Lost update at READ COMMITTED (read in the app, write back a computed value)
-- T1: SELECT balance FROM accounts WHERE id = 1;       -- 100
-- T2: SELECT balance FROM accounts WHERE id = 1;       -- 100
-- T1: UPDATE accounts SET balance = 110 WHERE id = 1;  COMMIT;
-- T2: UPDATE accounts SET balance = 120 WHERE id = 1;  COMMIT;  -- T1's +10 is gone

-- Fix 1: let the database do the arithmetic (atomic read-modify-write)
UPDATE accounts SET balance = balance + 10 WHERE id = 1;

-- Fix 2: lock the row for the whole read-modify-write cycle
BEGIN;
  SELECT balance FROM accounts WHERE id = 1 FOR UPDATE;  -- 2nd caller waits here
  UPDATE accounts SET balance = 110 WHERE id = 1;        -- value computed by the app
COMMIT;

-- Fix 3: optimistic concurrency with a version column
UPDATE accounts
SET balance = 110, version = version + 1
WHERE id = 1 AND version = 7;  -- "UPDATE 0" => someone else won: re-read and retry

-- Fix 4: PostgreSQL REPEATABLE READ detects the conflict for you
BEGIN ISOLATION LEVEL REPEATABLE READ;
  SELECT balance FROM accounts WHERE id = 1;
  UPDATE accounts SET balance = 110 WHERE id = 1;
  -- if another transaction changed row 1 after our snapshot was taken:
  -- ERROR:  could not serialize access due to concurrent update  (40001)
COMMIT;
